+					entity->roles[entity_role_cnt++] = cbor_get_uint8(value);
 				}
-				entity->roles[entity_role_cnt++] = cbor_get_uint8(value);
+			} else {
+				g_set_error_literal(error,
+						    FWUPD_ERROR,
+						    FWUPD_ERROR_INVALID_DATA,
+						    "entity role item is not an uint or array");
+				return FALSE;
 			}
